    (300836, 100160, 9214, 'Mẩu shell mình hay dùng lại, để đây cho ai cần. (#80)', 'Thứ dễ bỏ sót là trường hợp rỗng. Phần lớn lỗi ở đoạn này không đến từ dữ liệu sai mà từ dữ liệu không có.', '["layout shift","critical CSS","preload"]'::jsonb, '["CSS","Trình duyệt"]'::jsonb, 1, NULL, 1, '[]'::jsonb, 'FRONTEND', now() - INTERVAL '300 days', now() - INTERVAL '300 days'),
