    (9298, 'ghi-chu-394.md', 'Thứ dễ bỏ sót là trường hợp rỗng. Phần lớn lỗi ở đoạn này không đến từ dữ liệu sai mà từ dữ liệu không có.', '["hiệu-năng","đo-đạc"]'::jsonb, '[]'::jsonb, now() - INTERVAL '203 days', now() - INTERVAL '203 days'),
    (9176, 'ghi-chu-395.md', 'Đoạn mã trên gom dữ liệu một lần rồi truyền xuống, thay vì để mỗi phần tự đi hỏi. Cách cũ trông gọn hơn khi đọc, nhưng số lượt gọi tăng tuyến tính theo số phần tử — thứ chỉ lộ ra khi dữ liệu đủ lớn.', '["đọc-sách"]'::jsonb, '[]'::jsonb, now() - INTERVAL '53 days', now() - INTERVAL '53 days'),
    (9072, 'ghi-chu-396.md', 'Điểm mấu chốt là thứ tự: phải đo trước khi sửa, và đo ở đúng tầng đang nghi ngờ. Đo ở tầng dễ đo nhất thường cho ra một con số đúng nhưng không liên quan.', '["phỏng-vấn"]'::jsonb, '["ghi-chu-395.md"]'::jsonb, now() - INTERVAL '114 days', now() - INTERVAL '114 days'),
    (9185, 'ghi-chu-397.md', 'Cấu hình này đặt một trần cứng ở phía máy chủ. Nó không làm truy vấn nhanh hơn; nó chỉ bảo đảm một truy vấn hỏng không kéo theo cả hệ thống.', '["devops","vận-hành"]'::jsonb, '[]'::jsonb, now() - INTERVAL '276 days', now() - INTERVAL '276 days'),
    (9361, 'ghi-chu-398.md', 'Cách tiếp cận này đánh đổi bộ nhớ lấy thời gian. Với dữ liệu nhỏ thì lỗ, với dữ liệu lớn thì lãi — nên con số ranh giới quan trọng hơn bản thân kỹ thuật.', '["frontend"]'::jsonb, '[]'::jsonb, now() - INTERVAL '215 days', now() - INTERVAL '215 days'),
    (9024, 'ghi-chu-399.md', 'Thứ dễ bỏ sót là trường hợp rỗng. Phần lớn lỗi ở đoạn này không đến từ dữ liệu sai mà từ dữ liệu không có.', '["ý-tưởng"]'::jsonb, '[]'::jsonb, now() - INTERVAL '245 days', now() - INTERVAL '245 days');

